+def assigned_credits(lines, release):
+    """Return assigned credits for the requested agreement."""
+    credits = {}
+    groups = {}
+    for line in lines:
+        if release == "1.0":
+            group = (line["account_id"], line["subscription_id"])
+        else:
+            group = line["account_id"]
+        groups.setdefault(group, []).append(line)
